const factFields=[['referenceFound','Reference found in demo records'],['quantityRequired','Quantity is required'],['evidenceRequired','Evidence is required'],['outOfScope','Outside warehouse scope'],['ownershipMismatch','Ownership mismatch'],['receivingMismatch','Receiving mismatch'],['inventoryMismatch','Inventory mismatch'],['missingItem','Missing item'],['wrongSku','Wrong SKU'],['damage','Warehouse damage'],['conflictingEvidence','Conflicting evidence'],['unverifiableEvidence','Evidence cannot be verified'],['sourceAvailable','Source records available (synthetic demo)'],['physicalInspection','Physical inspection needed'],['deadlineExceeded','Recorded deadline exceeded'],['returnReceived','Return received at warehouse'],['returnPosted','Return entered in inventory'],['repeatedIssue','Repeated issue confirmed'],['reopened','Case reopened'],['humanRequested','SME requested human review'],['informationOnly','Information-only enquiry'],['additionalInformation','More information needed'],['stockAdjustment','Stock adjustment requested'],['replacement','Replacement / repacking requested'],['refund','Refund / compensation requested'],['liability','Liability decision needed'],['unsupportedConclusion','Maker conclusion unsupported'],['calculationIncorrect','Calculation incorrect'],['ruleViolation','Business rule violation'],['checkerDisagreement','Maker / checker disagree'],['unableToInterpret','Unable to interpret complaint'],['apiFailure','AI / API failure'],['unsuccessfulHandling','Repeated handling failed'],['auditSelected','Selected for human audit'],['checksPassed','Required checks passed (synthetic)']];
const beforeRuleShow=showReport;showReport=function(id){beforeRuleShow(id);const r=visibleReports().find(r=>r.id===id);if(!r)return;if(r.ai?.routing&&role!=='sme')$('#modalBody').append(`<details class="card p-4 mt-4 text-xs"><summary>Rule matches</summary><b>Matched business rules · ${RULE_VERSION}</b>${r.ai.routing.matches.map(x=>`<p class="mt-2"><b>R${x.id} · ${esc(x.title)} → ${x.review}</b><br>${esc(x.description)}</p>`).join('')}${r.ai.routing.unconfigured.length?`<p class="mt-3 text-orange-700">Threshold not configured: ${esc(r.ai.routing.unconfigured.join(', '))}. Routed to Manager.</p>`:''}</details>`);
if(['warehouse','manager'].includes(role)&&!['Closed','Awaiting SME Confirmation'].includes(r.status))$('#modalBody').append(`<details class="border rounded-xl p-4 mt-5"><summary class="text-sm font-semibold cursor-pointer">Demo rule inputs · ပြန်လည်စစ်ဆေးရန်</summary><p class="text-xs muted mt-3">Explicit test signals only, not detected by an AI model. Unknown is not a verified record. Saving reruns all 39 rules.</p><form id="ruleInputs" data-id="${r.id}" class="mt-4 space-y-3">${factFields.map(([key,label])=>`<label class="block text-xs">${label}<select name="${key}" class="field mt-1">${[['','Unknown'],['true','Yes'],['false','No']].map(([v,t])=>`<option value="${v}" ${(r.facts?.[key]===true?'true':r.facts?.[key]===false?'false':'')===v?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}${[['valueMMK','Affected value (MMK)'],['affectedQuantity','Affected quantity'],['affectedOrders','Affected orders'],['attempts','Unsuccessful attempts']].map(([key,label])=>`<label class="block text-xs">${label}<input name="${key}" type="number" min="0" class="field mt-1" value="${esc(r.facts?.[key]??'')}"></label>`).join('')}<p class="text-xs muted">Numeric thresholds are unconfigured. Positive values requiring a threshold go to Manager.</p><button class="primary">Save inputs & reevaluate rules</button></form></details>`);
if(['warehouse','manager'].includes(role)&&r.ai?.state==='AI Review')$('#modalBody').append(`<form id="aiPermittedAction" data-id="${id}" class="space-y-3 border-t pt-4 mt-5"><p class="text-sm font-semibold">Permitted AI Review action</p><p class="text-xs muted">${esc(r.ai.routing?.action||'Reevaluate rules first')}</p><textarea name="note" required maxlength="1500" class="field" placeholder="Information request / scope explanation / record-based response"></textarea><button class="primary">Record reply for SME (demo)</button><p class="text-xs muted">No stock, refund or external message is performed.</p></form>`)};
$(document).on('submit','#ruleInputs',function(e){e.preventDefault();if(!['warehouse','manager'].includes(role))return;let r=reports.find(x=>x.id===$(this).data('id'));if(!r||['Closed','Awaiting SME Confirmation'].includes(r.status))return;let data=new FormData(this),facts={};for(const [key]of factFields){const v=data.get(key);if(v==='true'||v==='false')facts[key]=v==='true'}for(const key of ['valueMMK','affectedQuantity','affectedOrders','attempts']){const v=data.get(key);if(v!==''&&v!==null)facts[key]=Number(v)}r.facts=facts;runMaker(r);render();showReport(r.id);reviewCountToast('Rules evaluated → '+r.ai.state)});
function recordPermittedReply(r,text){if(!['warehouse','manager'].includes(role)||r.ai?.state!=='AI Review'||!text.trim())return false;const result=evaluateRules(r,reports);if(result.review!=='AI')return false;const collect=result.matches.some(x=>[1,2,3,4,5,24].includes(x.id));r.status=collect?'Waiting for SME':'Awaiting SME Confirmation';r.ai.state=collect?'Waiting for SME':'Resolution Prepared';if(!collect)r.resolution=text.trim();r.events.push({by:'AI Review reply (staff-entered demo)',text:text.trim()});aiSave();return true}
$(document).on('submit','#aiPermittedAction',function(e){e.preventDefault();const r=reports.find(x=>x.id===$(this).data('id'));if(r&&recordPermittedReply(r,new FormData(this).get('note'))){render();showReport(r.id);note('Reply recorded · '+r.status)}else note('Human review required or action not permitted.')});
// Reevaluate saved active cases once when loading this rules version. Keep accepted resolutions intact.
for(const r of reports){if(r.ai&&r.ai.routing?.version!==RULE_VERSION&&!['Closed','Awaiting SME Confirmation','Waiting for SME'].includes(r.status))runMaker(r)}
render();

function auditCurrentReports(){return reports.filter(r=>r.ai&&['AI Review','Human Review','Audit Review'].includes(r.ai.state)&&!['Closed','Awaiting SME Confirmation'].includes(r.status)).map(r=>{const result=evaluateRules(r,reports),expected=result.review+' Review',saved=r.ai.state==='Audit Review'?'Human Review':r.ai.state;const prior=(r.ai.routing?.matches||[]).map(x=>x.id).sort((a,b)=>a-b),current=result.matches.map(x=>x.id).sort((a,b)=>a-b);return {id:r.id,saved,expected,rules:current,ok:saved===expected&&r.status===expected&&JSON.stringify(prior)===JSON.stringify(current)}})}
const dashboardBeforeAudit=managerDashboard;managerDashboard=function(){return '<div class="flex justify-end mb-4"><button id="auditCurrentReports" class="primary">↻ Recheck current reports</button></div>'+dashboardBeforeAudit()};
$(document).on('click','#auditCurrentReports',function(){if(role!=='manager')return;const rows=auditCurrentReports(),mismatches=rows.filter(r=>!r.ok).length;modal('Current reports · Business rule recheck',`<p class="text-sm mb-4">${rows.length} active reviews checked · ${mismatches} mismatch(es)</p><p class="text-xs muted mb-4">Read-only check of current browser reports against rule.md routing. Approved / closed cases are excluded. No demo data generated.</p><div class="overflow-auto"><table class="w-full"><thead><tr><th>Report</th><th>Saved → Expected</th><th>Rules</th><th>Check</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.saved)} → ${esc(r.expected)}</td><td>${r.rules.map(n=>'R'+n).join(', ')}</td><td>${r.ok?'✓ Match':'⚠ Reevaluate case'}</td></tr>`).join('')||'<tr><td colspan="4">No pending reviews.</td></tr>'}</tbody></table></div>`);note('Rechecked '+rows.length+' current reviews · '+mismatches+' mismatch(es)')});
render();
